const body = $json.body ?? $json;
const activity = body.activity ?? {};
const operation = body.operation;
if (!['safety_review', 'recommend'].includes(operation)) throw new Error('unsupported operation');
if (operation === 'safety_review' && (!activity.title || !activity.purpose || !activity.description || !activity.location)) throw new Error('missing activity fields');
if (operation === 'recommend' && !Array.isArray(body.activities)) throw new Error('missing activities');
return [{ json: { requestId: String(body.requestId || crypto.randomUUID()), operation, activity, activities: body.activities || [], preferences: body.preferences || {}, normalizedText: `${activity.title || ''} ${activity.purpose || ''} ${activity.description || ''}`.normalize('NFKC').toLowerCase().replace(/[\s_\-.~!@#$%^&*()[\]{}:;,'"`/\\|]+/g, '') } }];

const input = $('검증 및 정규화').first().json;

function parseModelResult(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const cleaned = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(cleaned); } catch { return null; }
}

const content = $json?.choices?.[0]?.message?.content ?? $json?.output_text ?? $json?.response ?? $json?.content;
const parsed = parseModelResult(content);
const providerFailed = Boolean($json?.error) || !parsed;

if (input.operation === 'recommend') {
  const allowedIds = new Set((input.activities || []).map((activity) => String(activity.id || '')).filter(Boolean));
  const recommendations = providerFailed || !Array.isArray(parsed?.recommendations) ? [] : parsed.recommendations
    .map((item) => ({ activityId: String(item?.activityId || item?.id || ''), reason: String(item?.reason || ''), fit: Math.max(0, Math.min(1, Number(item?.fit) || 0)) }))
    .filter((item) => allowedIds.has(item.activityId) && item.reason)
    .slice(0, 3);
  return [{ json: { requestId: input.requestId, recommendations, message: recommendations.length ? '' : '조건에 맞는 활동이 없습니다. 잠시 후 다시 시도해 주세요.', policyVersion: parsed?.policyVersion || 'recommendation-v1' } }];
}

const result = providerFailed ? { decision: 'manual_review', categories: [], confidence: 'low', explanation: '의미 검토 서비스를 사용할 수 없어 운영자 검토로 전환했습니다.', guidance: '잠시 후 다시 시도하거나 운영자 검토를 요청해 주세요.' } : parsed;
const decisionMap = { allow: 'approved', approved: 'approved', revise: 'held', block: 'held', held: 'held', review: 'manual_review', manual_review: 'manual_review', unavailable: 'unavailable' };
const decision = decisionMap[result.decision] || (result.risk === 'high' ? 'held' : 'manual_review');
return [{ json: { requestId: input.requestId, decision, categories: Array.isArray(result.categories) ? result.categories.slice(0, 5) : [], confidence: ['high', 'medium', 'low'].includes(result.confidence) ? result.confidence : 'low', explanation: String(result.explanation || '검토 결과를 확인해 주세요.'), guidance: String(result.guidance || '내용을 수정하거나 운영자 검토를 요청해 주세요.'), policyVersion: result.policyVersion || 'safety-v1' } }];
